import{Z as e,et as t,mt as n,s as r,tt as i}from"./chunks/framework.DIZxrxCz.js";import"./chunks/assets.tD9y118P.js";var a=JSON.parse(`{"title":"Dataset","description":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support.","frontmatter":{"title":"Dataset","description":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/dataset.html"}]],"sort":700},"headers":[],"relativePath":"en/synceta/dataset.md","filePath":"en/synceta/dataset.md","lastUpdated":1785655116000}`),o={name:`en/synceta/dataset.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[i(`<h1 id="dataset" tabindex="-1">Dataset <a class="header-anchor" href="#dataset" aria-label="Permalink to “Dataset”">​</a></h1><h2 id="what-is-a-dataset" tabindex="-1">What is a Dataset? <a class="header-anchor" href="#what-is-a-dataset" aria-label="Permalink to “What is a Dataset?”">​</a></h2><p>A dataset plays the role of automatically mapping pre-generated mockup data in a Key-Value structure to variables set in a scenario. You can generate mockup data based on pre-defined variables, and AI can automatically generate suitable data for the variables.</p><h2 id="create-a-dataset" tabindex="-1">Create a Dataset <a class="header-anchor" href="#create-a-dataset" aria-label="Permalink to “Create a Dataset”">​</a></h2><p>The dataset is designed with a structure similar to an Excel sheet, making it familiar to users and easy to create and manage.</p><p>You can freely add and delete variables and rows, and it provides a function to load variable values pre-set in the scenario. You can import pre-generated data from an Excel file, and after setting variables, you can automatically generate mockup data using AI.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>Right-click the sheet</li></ul></div><p><img src="/docs/assets/dataset.5iXXPzxJ.png" alt="image" loading="lazy"></p><h2 id="create-with-excel" tabindex="-1">Create with Excel <a class="header-anchor" href="#create-with-excel" aria-label="Permalink to “Create with Excel”">​</a></h2><h4 id="excel-form-download" tabindex="-1">Excel form <a href="./image/dataset/dataset_form.xlsx">Download</a> <a class="header-anchor" href="#excel-form-download" aria-label="Permalink to “Excel form Download”">​</a></h4><p><img src="/docs/assets/exel.CL7tt1gh.png" alt="image" loading="lazy"></p><h2 id="automatic-generation-using-ai" tabindex="-1">Automatic Generation using AI <a class="header-anchor" href="#automatic-generation-using-ai" aria-label="Permalink to “Automatic Generation using AI”">​</a></h2><p>After setting variables, click &#39;Auto-fill data with AI&#39;, and the AI will automatically generate mockup data that matches the variables.</p><ul><li>Loading <img src="/docs/assets/dataset_loading.DBtE2YtU.png" alt="image" loading="lazy"></li><li>Screen after data generation <img src="/docs/assets/dataset_ai.CDuljMGU.png" alt="image" loading="lazy"></li></ul><h2 id="apply-dataset" tabindex="-1">Apply Dataset <a class="header-anchor" href="#apply-dataset" aria-label="Permalink to “Apply Dataset”">​</a></h2>`,15),e(`iframe`,{width:`100%`,height:`400`,src:`https://www.youtube.com/embed/d2RU8aabXIQ`,frameborder:`0`,allowfullscreen:``,allow:`autoplay; encrypted-media`},null,-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};